products=json.loads((p/'productos.json').read_text())
nav=[('index.html','Inicio'),('nosotros.html','Nosotros'),('productos.html','Productos'),('clientes.html','Clientes'),('contacto.html','Contacto')]
def link(text='Conversemos por WhatsApp',msg='Hola, quisiera consultar por los productos Del Bosque.'):
 from urllib.parse import quote
 return f'<a class="button" href="https://wa.me/56998220830?text={quote(msg)}" target="_blank" rel="noopener noreferrer">{text} <span aria-hidden="true">↗</span></a>'
def cards():
 return '<div class="product-grid">'+''.join(f'<article class="product-card" data-category="{x["category"]}" data-name="{x["name"]}"><div class="product-art art-{i}" aria-hidden="true"><span class="product-number">0{i+1}</span><span class="product-letter">{["Jm","Ah","Ds"][i%3]}</span><span class="art-caption">DEL BOSQUE / {x["category"].upper()}</span></div><div class="product-body"><p class="eyebrow">{x["category"]}</p><h2>{x["name"]}</h2><p>{x["description"]}</p><p class="price">{("$" + format(x["price"], ",").replace(",", ".") + " CLP") if x["price"] is not None else "Precio a consultar"}</p><p class="small">Presentaciones y ficha técnica: consultar.</p><button class="button secondary add-product" data-id="{x["id"]}" type="button">Agregar a mi consulta <span aria-hidden="true">+</span></button><details><summary>Antes de elegir</summary><p>Solicita la etiqueta, indicaciones de uso y documentación técnica correspondiente. La compatibilidad, dosificación y precauciones dependen del producto específico.</p></details></div></article>' for i,x in enumerate(products))+'</div>'
hero='<section class="hero container"><div><p class="eyebrow">PRODUCTOS QUÍMICOS DEL BOSQUE · CHILE</p><h1>La limpieza empieza con una <em>buena elección.</em></h1><p class="lead">Productos de limpieza para tu negocio, tu trabajo y tu hogar. Conoce nuestras líneas y conversemos sobre lo que necesitas.</p><div class="actions"><a class="button" href="productos.html">Explorar productos <span>↗</span></a><a class="text-link" href="nosotros.html">Conoce Del Bosque →</a></div><p class="hero-note">EMPRESAS Y PARTICULARES &nbsp; / &nbsp; CONTACTO DIRECTO</p></div><div class="hero-art" aria-label="Composición gráfica de las tres líneas de productos"><div class="orbit"></div><p class="art-top">DEL BOSQUE<br><small>Lo esencial, bien elegido.</small></p><div class="sample sample-one"><span>01 / LIMPIEZA</span><strong>Jabón<br>mecánico</strong><b>Jm</b></div><div class="sample sample-two"><span>02 / SUPERFICIES</span><strong>Antihongos</strong><b>Ah</b></div><div class="sample sample-three"><span>03 / DESINFECCIÓN</span><strong>Desinfectantes</strong><b>Ds</b></div><p class="art-bottom">EXPLORA NUESTRAS LÍNEAS ↗</p></div></section>'
home=hero+'<div class="ribbon"><div class="container"><span>Para el trabajo cotidiano.</span><span>Para los espacios que cuidas.</span><span>Para elegir con información.</span></div></div><section class="container section"><div class="section-heading"><div><p class="eyebrow">NUESTRO CATÁLOGO</p><h2>Una solución para<br>cada necesidad.</h2></div><p>Comienza por una línea. Te ayudamos a consultar formatos, disponibilidad y antecedentes del producto.</p></div>'+cards()+'</section><section class="soft section"><div class="container split"><div><p class="eyebrow">CERCA DE LO QUE NECESITAS</p><h2>De tu taller<br>a tu hogar.</h2><a class="text-link" href="clientes.html">Explora las necesidades de cada espacio →</a></div><div class="rows"><article><span>01</span><div><h3>Trabajo y talleres</h3><p>Consulta por jabón mecánico y las indicaciones para su uso.</p></div></article><article><span>02</span><div><h3>Empresas y espacios compartidos</h3><p>Indica frecuencia de compra, cantidades y necesidades de limpieza.</p></div></article><article><span>03</span><div><h3>Hogar y uso cotidiano</h3><p>Elige según la superficie y las instrucciones de cada producto.</p></div></article></div></div></section>'
intro=lambda tag,title,text:f'<section class="container page-intro"><p class="eyebrow">{tag}</p><h1>{title}</h1><p class="lead">{text}</p></section>'
catalog=intro('CATÁLOGO','Encuentra tu próxima<br><em>solución de limpieza.</em>','Explora las líneas disponibles y arma tu consulta. Confirmaremos contigo los productos, formatos, precios y disponibilidad.')+'<section class="container catalog"><div class="filters" hidden><label>Buscar producto<input type="search" id="search" placeholder="Ej.: jabón mecánico"></label><label>Línea de productos<select id="category"><option value="">Todas las líneas</option>'+''.join(f'<option>{x["category"]}</option>' for x in products)+'</select></label><p id="results" role="status">3 productos</p></div>'+cards()+'<p id="empty" hidden>No encontramos productos con esos criterios. Prueba otra búsqueda.</p><aside class="quote-panel" hidden><div><h2>Mi consulta <span id="count">0</span></h2><p>Selecciona productos y ajusta las cantidades de envases que necesitas. Los formatos se confirman al cotizar.</p><ul id="quote-items"></ul><p id="quote-status" role="status" class="small"></p></div><a id="quote-send" class="button" href="https://wa.me/56998220830" target="_blank" rel="noopener noreferrer">Consultar por WhatsApp ↗</a></aside><noscript><p>Para armar una consulta de varios productos, activa JavaScript. También puedes <a href="contacto.html">contactarnos directamente</a>.</p></noscript></section>'
about=intro('NOSOTROS','Del Bosque.<br><em>Un trato cercano.</em>','Somos Productos Químicos del Bosque SpA. Nuestra oferta reúne productos de limpieza para empresas y particulares, con un canal directo para resolver consultas comerciales.')+'<section class="container section split"><div class="statement">Elegir bien.<br>Usar con información.<br><em>Cuidar tus espacios.</em></div><div><h2>Conoce lo que compras.</h2><p>Una buena elección parte por entender la necesidad: qué quieres limpiar, sobre qué superficie y en qué condiciones se utilizará el producto.</p><p>Por eso, nuestro catálogo es un punto de partida para conversar sobre alternativas, formatos e información técnica antes de comprar.</p><a class="text-link" href="contacto.html">Cuéntanos qué necesitas →</a></div></section><section class="soft section"><div class="container split"><div><p class="eyebrow">NUESTRA TRAYECTORIA</p><h2>La historia detrás<br>de Del Bosque.</h2></div><div><p>Estamos preparando esta sección con los antecedentes de la empresa, sus principales hitos y fotografías de su actividad.</p><p>Pronto podrás conocer más sobre las personas y el trabajo detrás de nuestros productos.</p></div></div></section>'
clients=intro('EMPRESAS Y PARTICULARES','Distintos espacios.<br><em>Una atención cercana.</em>','Estas son algunas necesidades sobre las que puedes consultarnos. La elección final depende del producto, su etiqueta y su uso autorizado.')+'<section class="container section rows"><article><span>01</span><div><h2>Talleres y trabajo mecánico</h2><p>Consulta por jabón mecánico, presentaciones y cantidades para tu equipo.</p></div></article><article><span>02</span><div><h2>Negocios y comunidades</h2><p>Conversemos sobre tus necesidades de limpieza, volúmenes y frecuencia de reposición.</p></div></article><article><span>03</span><div><h2>Hogares</h2><p>Indícanos la superficie y el uso que buscas para consultar una alternativa.</p></div></article></section><section class="soft section"><div class="container"><p class="eyebrow">CLIENTES Y EXPERIENCIAS</p><h2>Historias que podremos compartir.</h2><p>Este espacio reunirá referencias y experiencias de clientes, con su autorización. Por ahora, puedes conversar directamente con nosotros.</p>'+link()+'</div></section>'
contact=intro('CONTACTO','Hablemos de<br><em>lo que necesitas.</em>','Cuéntanos qué producto buscas, la cantidad aproximada y tu comuna. Te contactas directamente con Del Bosque a través de WhatsApp.')+'<section class="container section split"><div><h2>Contacto directo</h2><p class="contact-number"><a href="tel:+56998220830">+56 9 9822 0830</a></p>'+link()+'<p>Productos Químicos del Bosque SpA<br>RUT: 77.051.484-3</p><h3>Dirección de referencia</h3><p>Vecinal Nº 797, El Bosque, Santiago.<br>Consulta antes de acudir por atención o retiro.</p><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=Vecinal+797+El+Bosque+Santiago" target="_blank" rel="noopener noreferrer">Ver ubicación en Google Maps ↗</a></div><form id="contact-form"><h2>Prepara tu consulta</h2><label>Tu nombre<input name="name" required maxlength="80" autocomplete="name"></label><label>Empresa (opcional)<input name="company" maxlength="100" autocomplete="organization"></label><label>Comuna<input name="city" required maxlength="80" autocomplete="address-level3"></label><label>¿Qué necesitas?<textarea name="message" required maxlength="1500" rows="4" placeholder="Producto, cantidad y uso previsto"></textarea></label><button class="button" type="submit">Preparar mensaje para WhatsApp ↗</button><p class="small">Este formulario prepara un mensaje en tu dispositivo. Tú decides enviarlo en WhatsApp. No guardamos estos datos en el sitio.</p><a id="contact-send" class="button secondary" hidden target="_blank" rel="noopener noreferrer">Abrir WhatsApp con mi mensaje ↗</a><p id="contact-status" role="status"></p><noscript>Contacta mediante el enlace de WhatsApp que aparece en esta página.</noscript></form></section>'
info=intro('INFORMACIÓN TÉCNICA','Elegir con información.<br><em>Usar con cuidado.</em>','Antes de utilizar un producto, revisa su etiqueta y solicita la documentación correspondiente a su formulación y uso.')+'<section class="container section rows"><article><span>01</span><div><h2>Etiqueta e instrucciones</h2><p>Revisa el uso previsto, superficies compatibles, precauciones y condiciones de aplicación indicadas por el fabricante. No deduzcas dosificaciones a partir del nombre de una categoría.</p></div></article><article><span>02</span><div><h2>Hoja de datos de seguridad</h2><p>El D.S. 57/2019 regula la clasificación y el etiquetado de sustancias y mezclas peligrosas e incluye requisitos sobre sus hojas de datos de seguridad. Su aplicación depende del producto y su ámbito regulatorio.</p><a href="https://www.bcn.cl/leychile/Navegar?idNorma=1155752" target="_blank" rel="noopener noreferrer">Consultar D.S. 57/2019 en BCN ↗</a></div></article><article><span>03</span><div><h2>Desinfectantes y registro sanitario</h2><p>El ISP controla el registro de desinfectantes de uso sanitario y doméstico bajo el D.S. 157/2005. Solicita el registro del producto específico y verifica sus usos autorizados.</p><a href="https://www.ispch.cl/ambientes-y-alimentos/unidad-de-plaguicidas-y-desinfectantes/" target="_blank" rel="noopener noreferrer">Consultar información oficial del ISP ↗</a></div></article></section><div class="container notice"><p>Estas referencias generales no acreditan certificaciones ni registros de los productos del catálogo. La documentación de cada producto debe revisarse antes de definir su aplicación.</p></div>'
for filename,title,body in [('index.html','Limpieza para empresas y hogares',home),('productos.html','Catálogo de productos',catalog),('nosotros.html','Quiénes somos',about),('clientes.html','Empresas y particulares',clients),('contacto.html','Contacto y cotizaciones',contact),('informacion-tecnica.html','Información técnica y uso responsable',info)]:
 html='<!doctype html><html lang="es-CL"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+title+' | Del Bosque</title><meta name="description" content="'+title+'. Productos Químicos del Bosque: jabón mecánico, antihongos y desinfectantes. Consulta formatos y disponibilidad."><link rel="stylesheet" href="style.css"><script src="script.js" defer></script></head><body><a class="skip" href="#main">Saltar al contenido</a><div class="topbar">Productos de limpieza · Empresas y particulares <a href="contacto.html">Conversemos ↗</a></div><header class="site-header"><div class="container nav-wrap"><a class="brand" href="index.html" aria-label="Del Bosque, inicio"><span class="brand-icon" aria-hidden="true">db.</span><span>del bosque<small>PRODUCTOS QUÍMICOS</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation" hidden>Menú</button><nav id="navigation" aria-label="Navegación principal">'+''.join(f'<a href="{url}"'+(' aria-current="page"' if url==filename else '')+f'>{label}</a>' for url,label in nav)+'</nav></div></header><main id="main">'+body+'</main><section class="closing"><div class="container"><div><p class="eyebrow">EL SIGUIENTE PASO ES SIMPLE</p><h2>Cuéntanos qué necesitas limpiar.</h2></div>'+link('Consultar por WhatsApp')+'</div></section><footer class="container"><div><a class="brand" href="index.html">del bosque</a><p>Productos Químicos del Bosque SpA<br>El Bosque, Santiago · Chile</p></div><div><a href="productos.html">Catálogo</a><a href="informacion-tecnica.html">Información técnica</a><a href="contacto.html">Contacto</a></div><p class="small">© <span id="year">2026</span> Del Bosque.<br>Precios, formatos y disponibilidad sujetos a confirmación.</p></footer></body></html>'
 (p/filename).write_text(html)
